CH = dict(num=13, title="The Value of Work", tag="Economics", theme="Economic vs non-economic activities, value addition",
 intro="People do many kinds of work every day — some for money and some out of love, care or service. This chapter distinguishes economic from non-economic activities, shows how people are paid (salary, wage, fee, payment in kind), explains value addition and highlights the importance of sevā and community participation.",
 big_questions=["What are the different types of activities that people engage in?", "What is their contribution to our everyday lives?"],
 blocks=[
 ("h2", "13.1 Economic and Non-Economic Activities"),
 ("p", "Anu and Kabir see that everyone around them does many things: Geeta Aunty is an Indian Air Force pilot (salary); Kabir's grandfather, a retired BSF officer, tends the garden, runs errands and teaches Geography free; Anu's parents run a uniform and garment shop, and her mother teaches knitting voluntarily; her brother Rohan is a software engineer (salary) who volunteers teaching computer skills on weekends."),
 ("table", ["", "Economic activities", "Non-economic activities"], [
  ["Meaning", "Involve **money or money's worth**; done in exchange for money or its equivalent", "Do **not generate income or wealth**; done from gratitude, love, care and respect"],
  ["Examples", "Business person selling school bags; farmer selling produce; lawyer earning a fee; truck driver carrying goods; factory workers; pilot on salary; Rohan's software job", "Parents cooking for the family or helping with homework; youth caring for grandparents; family renovating the home; Rohan teaching computers free; grandfather teaching neighbourhood kids"],
  ["Return", "Salary, wage, fee, profit, payment in kind", "Satisfaction, gratitude, well-being, stronger relationships"]]),
 ("note", "NOTE", "The **same person** can do both: Rohan earns a salary at his company (economic) and volunteers at weekends (non-economic). A teacher teaching for a salary is economic; teaching the same lesson free is non-economic."),
 ("p", "**Terms:** *market* — place where goods and services are exchanged (mostly for money); *fee* — payment for professional advice or service (doctor, lawyer); *money's worth* — the monetary value of an object based on the benefit it gives; *salary* — fixed regular (monthly) payment by an employer."),
 ("h2", "13.2 Types of Economic Activities and Ways of Payment"),
 ("p", "From Kavya's visit to the village Kamlapur:"),
 ("table", ["Person", "Work", "Payment"], [
  ["Kavya's uncle", "Bulldozer technician in a construction company (highway under construction; will cut travel time from 5 hours to 2)", "Monthly **salary**"],
  ["Kavya's aunt", "Employee at the village post office; also online classes for exam preparation", "Monthly **salary**; weekly **fee**"],
  ["Sahil", "Farm labourer driving a tractor on a farmer's land", "Daily **wage** — partly cash, partly **mangoes** (**payment in kind**)"],
  ["Rajesh", "Carpenter making furniture", "Income from **selling** furniture"]]),
 ("table", ["Form of payment", "Meaning", "Example"], [
  ["Salary", "Fixed regular payment, usually monthly, by an employer", "Pilot, software engineer, post-office employee"],
  ["Wage", "Payment by employer for a specific period of work (often daily)", "Farm labourer"],
  ["Fee", "Payment for professional advice or service", "Doctor, lawyer, online tutor"],
  ["Payment in kind", "Non-cash payment for work done", "Mangoes to Sahil"],
  ["Sale income / profit", "Money earned by selling goods", "Shopkeeper, farmer, carpenter"]]),
 ("h2", "13.3 Value Addition"),
 ("note", "DEFINITION", "**Value addition** — economic activities add value at each stage of transforming something into another form."),
 ("p", "**Example:** carpenter Rajesh buys wood for **₹600**, uses tools and materials and makes a chair sold for **₹1,000**. The extra **₹400** (1,000 − 600) is the value of his **skill, time and effort**. He has added value to the wood by making it furniture. Buying and selling both involve payment, so all are economic activities."),
 ("table", ["Activity", "Creates monetary value?"], [
  ["Baker, tailor, doctor, scientist", "Yes"],
  ["Farmers repairing their own tractor", "Yes, helps income (production) — repair is part of farming"],
  ["Parents cooking dinner for the family", "No (non-economic)"],
  ["Caring for a sick grandparent", "No (non-economic)"]]),
 ("h2", "13.4 Importance of Non-Economic Activities"),
 ("ul", ["They create no money but bring great value: satisfaction, gratitude and contribution to society without expecting anything in return.",
  "**Sevā** = selfless service. Seen in temples, gurudwaras, mosques and churches — e.g. **langar** (community kitchen) at gurudwaras (Golden Temple) serves free food to every visitor; temples distribute **prasād**.",
  "**Swachh Bharat Abhiyan** — collective effort of citizens to keep surroundings clean (homes, streets, parks); individual efforts add up to a clean neighbourhood and nation.",
  "**Van Mahotsav** (festival of forests) — community tree-plantation drives to promote awareness of trees and conservation of forests.",
  "Festivals involve community members decorating, cooking and sharing — non-economic but valuable.",
  "Non-economic activities contribute to **social welfare, personal well-being** and a better **quality of life**."]),
 ("note", "REMEMBER", "Vivekananda: do any work as worship — with full devotion. Both kinds of work matter: economic activities earn a living; non-economic activities build a caring society."),
 ("h2", "13.5 Quick Reference"),
 ("qa", [
  ("Define economic activities with examples.", "Activities done for money or money's worth — a farmer selling produce, a lawyer taking fees, factory workers."),
  ("Define non-economic activities with examples.", "Activities without income, done from love, care or gratitude — cooking for family, caring for grandparents."),
  ("Can the same activity be economic and non-economic?", "Yes — teaching for a salary is economic; teaching free as a volunteer is non-economic."),
  ("What is the difference between salary and wage?", "Salary is a fixed regular (monthly) payment; wage is payment for a specific period of work, often daily."),
  ("What is payment in kind?", "Non-cash payment for work, e.g. mangoes given to Sahil."),
  ("What is a fee?", "Payment for professional services such as a doctor's or lawyer's."),
  ("What is value addition?", "The increase in value as a good is transformed through skill, time and effort."),
  ("Explain value addition with the carpenter example.", "Wood costing ₹600 becomes a chair sold for ₹1,000; the extra ₹400 is Rajesh's added value."),
  ("What is sevā?", "Selfless service without expecting anything in return, e.g. langar."),
  ("Give two examples of community participation.", "Swachh Bharat Abhiyan and Van Mahotsav."),
  ("Why do non-economic activities matter?", "They support social welfare, personal well-being and a better quality of life."),
  ("Is a traditional festival gathering economic?", "Mostly non-economic, but it holds social value through togetherness.")]),
 ],
 takeaways=["Activities are **economic** (for money or money's worth) or **non-economic** (for love, care, service).",
  "People are paid through **salary, wage, fee, sale income and payment in kind**.",
  "Economic activities create **value addition** (e.g. ₹600 wood → ₹1,000 chair).",
  "Non-economic activities such as **sevā, Swachh Bharat Abhiyan and Van Mahotsav** strengthen society.",
  "Both types of work are valuable for a good life."])
